# =====================================================================================
# 서사 단위 레이아웃(최종). 규칙: 번호 띠 또는 소제목(가·나·다)이 나오면 새 서사가 시작되고, 다음 번호 띠·소제목 직전까지가 하나의 레이아웃이다.
# 위 PARTS(부품 견본: 사다리·박스 등 하나씩)는 서사 레이아웃을 이루는 재료이고 블록 카드의 견본으로만 쓴다.
# =====================================================================================
PARTS = LAYOUTS


def _segs(letter):
    """레시피 노드열을 서사 단위로 자른다: 평가내용 띠는 쪽 머리로 빼고, 번호 띠 + 소제목마다 한 서사."""
    out = []; cur = []
    for n in K[letter]:
        if n['t'] == 'eval':
            continue
        if n['t'] == 'sub' and cur and any(m['t'] == 'sub' for m in cur):
            out.append(cur); cur = []
        cur.append(n)
    if cur: out.append(cur)
    return out


def _part(pid, i): return PARTS[int(pid[1:]) - 1]['nodes'][i]


