def catalog_spec():
    """PL 6쪽을 이어 붙인 카탈로그(홀수·짝수쪽 교대)"""
    nodes = []
    for i, pid in enumerate(PL_NODES):
        if i: nodes.append(dict(t='newpage'))
        nodes += PL_NODES[pid]
    return dict(start_no=93, first='odd', note=NOTE, nodes=nodes)

